"""Compliance READINESS (pre-audit): maps technical evidence from the audit to the controls of the frameworks companies get
assessed against (SOC 2, ISO 27001:2022, HIPAA Security Rule, GDPR, PCI DSS 4.0, NIST CSF 2.0, DORA, EU AI Act, WCAG 2.2/VPAT).
It does NOT certify anything: it shows where you stand, closes technical gaps early and prepares the evidence an auditor will request.

Tokens used by controls:  <roadmap-id> (must be OK) | !RULE (confirmed finding RULE must be absent) | f:family (no confirmed finding in family) | sbom | licenses | nologsecrets"""
import csv, io, os, re

AI_SDK = r"\b(openai|anthropic|langchain|llama[_-]?index|transformers|torch|tensorflow|google-generativeai|@google/generative-ai|cohere|mistralai|huggingface|vertexai|ollama|replicate|@ai-sdk|ai-sdk|litellm|sentence-transformers)\b"

F = {}
def fw(id, name, ref, controls, applies=None): F[id] = dict(id=id, name=name, ref=ref, controls=controls, applies=applies)

