def _sig(rm, findings, metrics, kinds, deps_text, sbom):
    items = {}
    if rm:
        for d in rm["dimensions"].values():
            for i in d["items"]: items[i["id"]] = i
    conf = [f for f in findings if f["status"] == "confirmed"]
    rules = {f["rule"] for f in conf}; fams = {f["family"] for f in conf}
    return items, rules, fams


def evaluate(rm, findings, metrics, kinds, deps_text, sbom, which=None):
    items, rules, fams = _sig(rm, findings, metrics, kinds, deps_text, sbom or {})
    dm = metrics.get("domain") or {}
    for d in (dm.get("dimensions") or {}).values():
        for i in d["items"]: items[i["id"]] = i
    fin = bool(set(dm.get("domains") or []) & {"fintech", "banking"})
    conf = [f for f in findings if f["status"] == "confirmed"]
    ai = bool(re.search(AI_SDK, deps_text, re.I)); web = bool(set(kinds) & {"frontend", "web"})
    ind = {i["id"] for i in ((metrics.get("profile") or {}).get("industry") or [])}
    fin = fin or bool(ind & {"fintech", "insurance"})
    health = bool(ind & {"health"}) or "health" in (dm.get("domains") or [])
    pay = bool(ind & {"fintech", "ecommerce", "marketplace"}) or bool(re.search(r"\b(stripe|adyen|braintree|paypal|mercadopago|square|authorize\.net|checkout\.com)\b", deps_text, re.I)) or fin
    ai = ai or "ai" in ind
    web = web or bool(set(kinds) & {"pwa"})
    def ev(tok):
        if tok.startswith("!"): return (tok[1:] not in rules, f"no {tok[1:]} findings")
        if tok.startswith("f:"): return (tok[2:] not in fams, f"no {tok[2:]} findings")
        if tok == "sbom": return ((sbom or {}).get("components", 0) > 0 if sbom is not None else None, "SBOM generated from lockfiles")
        if tok == "licenses": return ((not (sbom or {}).get("strong_copyleft")) if (sbom or {}).get("components") else None, "no strong-copyleft licenses")
        if tok == "nologsecrets": return ("LOG-SECRET" not in rules, "no secrets written to logs")
        i = items.get(tok)
        return (i["ok"], i["title"]) if i else (None, tok)
    out = []
    for k, f in F.items():
        if which and k not in which: continue
        applies = None if (which and k in which) else f["applies"]
        if applies == "ai" and not ai: continue
        if applies == "web" and not web: continue
        if applies == "fin" and not fin: continue
        if applies == "health" and not health: continue
        if applies == "pay" and not pay: continue
        ctrls, p, g, m, na = [], 0, 0, 0, 0
        for cid, title, tokens, evid in f["controls"]:
            res = [(t, *ev(t)) for t in tokens]; known = [r for r in res if r[1] is not None]
            if not tokens: st = "manual"
            elif not known: st = "n/a"
            elif all(r[1] for r in known): st = "pass"
            else: st = "gap"
            missing = [r[2] for r in known if not r[1]]; okl = [r[2] for r in known if r[1]]
            fnd = sorted({x["id"] for x in conf if (x["rule"] in [t[1:] for t in tokens if t.startswith("!")] or x["family"] in [t[2:] for t in tokens if t.startswith("f:")])})[:6]
            ctrls.append(dict(id=cid, title=title, status=st, ok=okl, missing=missing, auditor_asks=evid, findings=fnd, needs=[t for t in tokens if t in items]))
            p += st == "pass"; g += st == "gap"; m += st == "manual"; na += st == "n/a"
        auto = p + g
        out.append(dict(id=k, name=f["name"], ref=f["ref"], readiness=round(100 * p / auto) if auto else None, pass_=p, gap=g, manual=m, na=na, total=len(ctrls), automated=auto, controls=ctrls))
    return dict(frameworks=out, ai_detected=ai, note="Readiness = share of automatically checkable controls with technical evidence in place. It is NOT a certification; manual controls (policies, training, vendors, physical) need organizational evidence.")


def write_pack(dest, comp, findings, metrics, meta, sbom_bom, policies, lang="en"):
    os.makedirs(dest, exist_ok=True); files = []
    def w(name, text, sub=None):
        d = os.path.join(dest, sub) if sub else dest; os.makedirs(d, exist_ok=True); open(os.path.join(d, name), "w", encoding="utf-8").write(text); files.append((sub + "/" if sub else "") + name)
    conf = [f for f in findings if f["status"] == "confirmed"]; sev = {}
    for f in conf: sev[f["severity"]] = sev.get(f["severity"], 0) + 1
    rm = metrics.get("roadmap") or {}
    lines = [f"# Audit evidence pack - {meta.get('repo', '')}", "", f"Generated by {meta.get('tool', 'PN-Ultra-Audit')} on {meta.get('date', '')} (ref `{meta.get('source_ref', '')}`). **Pre-audit readiness material - not a certification.**", "",
             "## How to use this pack", "1. Fix the technical **gaps** listed in `remediation-plan.md` (re-run the audit until they close).", "2. Fill the **policy templates** in `policy-templates/` and approve them (management signature + date).",
             "3. Collect the documents listed in `evidence-requests.md` (screenshots/exports with dates).", "4. Hand the matrix, SBOM, findings and evidence to your certification auditor / assessor.", "",
             "## Snapshot", f"- Confirmed findings: {len(conf)} ({', '.join(f'{k}: {v}' for k, v in sev.items())})", f"- Professional level: {rm.get('level', '?')}/5 {rm.get('level_name', '')} (score {rm.get('score', '?')}/100)",
             f"- SBOM components: {(metrics.get('sbom') or {}).get('components', 'n/a')}", "", "## Readiness by framework", "", "| Framework | Readiness | Pass | Gap | Manual | N/A |", "|---|---|---|---|---|---|"]
    for f in comp["frameworks"]: lines.append(f"| {f['name']} | {str(f['readiness']) + '%' if f['readiness'] is not None else 'n/a'} | {f['pass_']} | {f['gap']} | {f['manual']} | {f['na']} |")
    lines += ["", f"> {comp['note']}"]
    w("README.md", "\n".join(lines) + "\n")
    buf = io.StringIO(); cw = csv.writer(buf); cw.writerow(["framework", "control", "title", "status", "technical_evidence", "missing_evidence", "related_findings", "what_the_auditor_will_ask_for"])
    for f in comp["frameworks"]:
        for c in f["controls"]: cw.writerow([f["name"], c["id"], c["title"], c["status"], "; ".join(c["ok"]), "; ".join(c["missing"]), " ".join(c["findings"]), c["auditor_asks"]])
    w("control-matrix.csv", buf.getvalue())
    buf = io.StringIO(); cw = csv.writer(buf); cw.writerow(["id", "severity", "type", "category", "rule", "title", "file", "line", "cwe", "owasp", "effort_min"])
    for x in conf: cw.writerow([x["id"], x["severity"], x["type"], x["category"], x["rule"], x["title"], x["location"]["file"], x["location"]["line"], " ".join(x.get("cwe", [])), " ".join(x.get("owasp", [])), x["effort_min"]])
    w("findings.csv", buf.getvalue())
    req = ["# Evidence requests by framework", "", "What assessors typically ask for. Collect dated screenshots/exports; keep them in a shared folder per control.", ""]
    for f in comp["frameworks"]:
        req += [f"## {f['name']}", f"_{f['ref']}_", "", "| Control | Status | Prepare this evidence |", "|---|---|---|"] + [f"| {c['id']} {c['title']} | {c['status']} | {c['auditor_asks']} |" for c in f["controls"]] + [""]
    w("evidence-requests.md", "\n".join(req))
    rp = ["# Remediation plan (gaps that block readiness)", "", "| Priority | Framework | Control | Missing technical evidence |", "|---|---|---|---|"]
    gaps = [(f["name"], c) for f in comp["frameworks"] for c in f["controls"] if c["status"] == "gap"]
    gaps.sort(key=lambda x: -len(x[1]["missing"]))
    for i, (fn, c) in enumerate(gaps, 1): rp.append(f"| {i} | {fn} | {c['id']} {c['title']} | {'; '.join(c['missing'])} |")
    rp += ["", "## Open critical/high findings (fix first)", ""] + [f"- **{x['id']}** [{x['severity']}] {x['title']} - `{x['location']['file']}:{x['location']['line']}`" for x in conf if x["severity"] in ("critical", "high")][:80]
    w("remediation-plan.md", "\n".join(rp) + "\n")
    if sbom_bom:
        import json; w("sbom.cdx.json", json.dumps(sbom_bom, indent=2))
    for n, t in policies.items(): w(n, t, "policy-templates")
    return files
